CREATE TABLE public.activity_holidays(day date PRIMARY KEY,name text NOT NULL CHECK(btrim(name)<>'')); GRANT SELECT ON public.activity_holidays TO authenticated; GRANT ALL ON public.activity_holidays TO service_role; ALTER TABLE public.activity_holidays ENABLE ROW LEVEL SECURITY; CREATE POLICY holidays_read ON public.activity_holidays FOR SELECT TO authenticated USING(is_staff(auth.uid()) OR has_role(auth.uid(),'client'));
CREATE TABLE public.activity_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pipeline_id uuid NOT NULL REFERENCES public.pipelines(id),name text NOT NULL CHECK(btrim(name)<>''),active boolean NOT NULL DEFAULT true,UNIQUE(pipeline_id,name)); GRANT SELECT ON public.activity_types TO authenticated; GRANT ALL ON public.activity_types TO service_role; ALTER TABLE public.activity_types ENABLE ROW LEVEL SECURITY; CREATE POLICY types_read ON public.activity_types FOR SELECT TO authenticated USING(is_staff(auth.uid()) OR has_role(auth.uid(),'client'));
CREATE TABLE public.activity_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_pipeline_id uuid NOT NULL REFERENCES public.client_pipelines(id),month date NOT NULL CHECK(month=date_trunc('month',month)::date),version integer NOT NULL DEFAULT 1,family_id uuid NOT NULL,previous_id uuid REFERENCES public.activity_plans(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','pending','changes_requested','approved','superseded')),comment text,created_by uuid,approved_by uuid,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(client_pipeline_id,month,version)); GRANT SELECT ON public.activity_plans TO authenticated; GRANT ALL ON public.activity_plans TO service_role; ALTER TABLE public.activity_plans ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.activity_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_id uuid NOT NULL REFERENCES public.activity_plans(id),occurrence_key uuid NOT NULL DEFAULT gen_random_uuid(),activity_type_id uuid REFERENCES public.activity_types(id),name text NOT NULL CHECK(btrim(name)<>''),quantity integer NOT NULL CHECK(quantity>0),publish_on date NOT NULL,owner_id uuid NOT NULL REFERENCES public.profiles(id),backup_id uuid NOT NULL REFERENCES public.profiles(id),CHECK(owner_id<>backup_id),UNIQUE(plan_id,occurrence_key)); GRANT SELECT ON public.activity_items TO authenticated; GRANT ALL ON public.activity_items TO service_role; ALTER TABLE public.activity_items ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.recurring_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_id uuid NOT NULL REFERENCES public.activity_plans(id),item_id uuid NOT NULL REFERENCES public.activity_items(id),family_id uuid NOT NULL,occurrence_key uuid NOT NULL,stage text NOT NULL CHECK(stage IN('preparation','approval','publish')),due_date date NOT NULL,original_due_date date NOT NULL,owner_id uuid NOT NULL REFERENCES public.profiles(id),backup_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'not_started' CHECK(status IN('not_started','in_progress','done','missed_review','closed','superseded')),done_at timestamptz,done_by uuid,review_reason text,notes text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(owner_id<>backup_id),UNIQUE(plan_id,occurrence_key,stage)); GRANT SELECT ON public.recurring_tasks TO authenticated; GRANT ALL ON public.recurring_tasks TO service_role; ALTER TABLE public.recurring_tasks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.activity_task_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES public.recurring_tasks(id),actor uuid,action text NOT NULL,reason text,old_due date,new_due date,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.activity_task_history TO authenticated; GRANT ALL ON public.activity_task_history TO service_role; ALTER TABLE public.activity_task_history ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.activity_can_read(_cp uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM client_pipelines cp JOIN clients c ON c.id=cp.client_id WHERE cp.id=_cp AND (is_manager(auth.uid()) OR (has_role(auth.uid(),'client') AND (my_client_id()=c.id OR my_client_id()=c.parent_client_id)) OR (is_staff(auth.uid()) AND EXISTS(SELECT 1 FROM client_staff_assignments a WHERE a.client_id=c.id AND a.pipeline_id=cp.pipeline_id AND a.user_id=auth.uid() AND NOT a.excluded)))) $$;
CREATE FUNCTION public.activity_can_head(_cp uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM client_pipelines cp WHERE cp.id=_cp AND is_pipeline_head(auth.uid(),cp.pipeline_id) AND EXISTS(SELECT 1 FROM client_staff_assignments a WHERE a.client_id=cp.client_id AND a.pipeline_id=cp.pipeline_id AND a.user_id=auth.uid() AND NOT a.excluded)) $$;
REVOKE ALL ON FUNCTION public.activity_can_read(uuid),public.activity_can_head(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activity_can_read(uuid),public.activity_can_head(uuid) TO authenticated,service_role;
CREATE POLICY plans_read ON public.activity_plans FOR SELECT TO authenticated USING(activity_can_read(client_pipeline_id) AND (NOT has_role(auth.uid(),'client') OR status<>'draft'));
CREATE POLICY items_read ON public.activity_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM activity_plans p WHERE p.id=plan_id));
CREATE POLICY recurring_read ON public.recurring_tasks FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM activity_plans p WHERE p.id=plan_id) AND NOT has_role(auth.uid(),'client'));
CREATE POLICY history_read ON public.activity_task_history FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM recurring_tasks t WHERE t.id=task_id));
CREATE FUNCTION public.activity_require_ready() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND must_change_password) THEN RAISE EXCEPTION 'Choose your private password before continuing'; END IF; END $$; REVOKE ALL ON FUNCTION public.activity_require_ready() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.activity_working_before(_date date,_days integer) RETURNS date LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d date:=_date;n int:=0; BEGIN IF _date IS NULL OR _days<0 OR _days>366 THEN RAISE EXCEPTION 'Invalid working-day offset'; END IF; WHILE n<_days LOOP d:=d-1; IF extract(isodow FROM d)<>7 AND NOT EXISTS(SELECT 1 FROM activity_holidays WHERE day=d) THEN n:=n+1; END IF; END LOOP; RETURN d; END $$; REVOKE ALL ON FUNCTION public.activity_working_before(date,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activity_working_before(date,integer) TO authenticated,service_role;
CREATE FUNCTION public.activity_settings(_kind text,_id text,_name text,_pipeline uuid DEFAULT NULL,_active boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM activity_require_ready(); IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin only'; END IF; IF _kind='holiday' THEN IF _active THEN INSERT INTO activity_holidays(day,name) VALUES(_id::date,btrim(_name)) ON CONFLICT(day) DO UPDATE SET name=excluded.name; ELSE DELETE FROM activity_holidays WHERE day=_id::date; END IF; ELSIF _kind='type' THEN IF _id IS NULL THEN INSERT INTO activity_types(pipeline_id,name,active) VALUES(_pipeline,btrim(_name),_active) ON CONFLICT(pipeline_id,name) DO UPDATE SET active=excluded.active; ELSE UPDATE activity_types SET name=btrim(_name),active=_active WHERE id=_id::uuid; END IF; ELSE RAISE EXCEPTION 'Unknown setting'; END IF; END $$; REVOKE ALL ON FUNCTION public.activity_settings(text,text,text,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activity_settings(text,text,text,uuid,boolean) TO authenticated;
CREATE FUNCTION public.save_activity_plan(_cp uuid,_month date,_items jsonb,_plan uuid DEFAULT NULL,_submit boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p activity_plans;oldp activity_plans;cp client_pipelines;r jsonb;id uuid;key uuid;own uuid;bak uuid;d date;ty uuid; BEGIN PERFORM activity_require_ready(); IF NOT activity_can_head(_cp) THEN RAISE EXCEPTION 'Assigned pipeline head only'; END IF; SELECT * INTO cp FROM client_pipelines WHERE id=_cp; IF cp.status='ended' OR client_on_hold(cp.client_id) OR NOT EXISTS(SELECT 1 FROM pipelines WHERE id=cp.pipeline_id AND code NOT IN('business_development')) THEN RAISE EXCEPTION 'An included active client pipeline is required'; END IF; IF _month IS NULL OR jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items)=0 THEN RAISE EXCEPTION 'Add at least one dated activity'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(_cp::text||date_trunc('month',_month)::date::text)); IF _plan IS NOT NULL THEN SELECT * INTO p FROM activity_plans WHERE id=_plan FOR UPDATE; IF p.id IS NULL OR p.client_pipeline_id<>_cp OR p.month<>date_trunc('month',_month)::date THEN RAISE EXCEPTION 'Plan not found'; END IF; END IF;
 IF p.id IS NULL OR p.status='approved' THEN oldp:=p; id:=gen_random_uuid(); INSERT INTO activity_plans(id,client_pipeline_id,month,version,family_id,previous_id,created_by) VALUES(id,_cp,date_trunc('month',_month)::date,coalesce((SELECT max(version)+1 FROM activity_plans WHERE client_pipeline_id=_cp AND month=date_trunc('month',_month)::date),1),coalesce(oldp.family_id,id),oldp.id,auth.uid()) RETURNING * INTO p; ELSIF p.status NOT IN('draft','changes_requested') THEN RAISE EXCEPTION 'Only drafts, requested changes or approved-plan revisions can be edited'; END IF;
 IF EXISTS(SELECT 1 FROM recurring_tasks t JOIN activity_items i ON i.id=t.item_id WHERE t.family_id=p.family_id AND t.status='done' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_items) x WHERE x->>'occurrence_key'=i.occurrence_key::text AND x->>'name'=i.name AND (x->>'quantity')::int=i.quantity AND (x->>'publish_on')::date=i.publish_on)) THEN RAISE EXCEPTION 'Keep completed activities unchanged in the new version'; END IF;
 DELETE FROM activity_items WHERE plan_id=p.id;
 FOR r IN SELECT * FROM jsonb_array_elements(_items) LOOP key:=coalesce(nullif(r->>'occurrence_key','')::uuid,gen_random_uuid()); own:=nullif(r->>'owner_id','')::uuid;bak:=nullif(r->>'backup_id','')::uuid;d:=(r->>'publish_on')::date;ty:=nullif(r->>'activity_type_id','')::uuid;
 IF d< p.month OR d>=(p.month+interval '1 month')::date THEN RAISE EXCEPTION 'Every publish date must be inside the plan month'; END IF;
 IF own IS NULL OR bak IS NULL OR own=bak OR (SELECT count(DISTINCT a.user_id) FROM client_staff_assignments a JOIN profiles pr ON pr.id=a.user_id AND pr.status='active' WHERE a.client_id=cp.client_id AND a.pipeline_id=cp.pipeline_id AND NOT a.excluded AND a.user_id IN(own,bak))<>2 THEN RAISE EXCEPTION 'Choose an assigned owner and a different assigned backup'; END IF;
 IF ty IS NOT NULL AND NOT EXISTS(SELECT 1 FROM activity_types WHERE id=ty AND pipeline_id=cp.pipeline_id AND active) THEN RAISE EXCEPTION 'Choose an active type from this pipeline'; END IF;
 INSERT INTO activity_items(plan_id,occurrence_key,activity_type_id,name,quantity,publish_on,owner_id,backup_id) VALUES(p.id,key,ty,btrim(r->>'name'),(r->>'quantity')::int,d,own,bak); END LOOP;
 UPDATE activity_plans SET status=CASE WHEN _submit THEN 'pending' ELSE 'draft' END,comment=NULL WHERE activity_plans.id=p.id; RETURN p.id; END $$;
REVOKE ALL ON FUNCTION public.save_activity_plan(uuid,date,jsonb,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_activity_plan(uuid,date,jsonb,uuid,boolean) TO authenticated;
CREATE FUNCTION public.decide_activity_plan(_plan uuid,_approve boolean,_comment text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p activity_plans;cp client_pipelines;i activity_items;s text;d date; BEGIN PERFORM activity_require_ready(); SELECT * INTO p FROM activity_plans WHERE id=_plan FOR UPDATE; SELECT * INTO cp FROM client_pipelines WHERE id=p.client_pipeline_id; IF NOT has_role(auth.uid(),'client') OR NOT EXISTS(SELECT 1 FROM clients c WHERE c.id=cp.client_id AND (c.id=my_client_id() OR c.parent_client_id=my_client_id())) THEN RAISE EXCEPTION 'Only this hotel owner can decide the plan'; END IF; IF p.status<>'pending' THEN RAISE EXCEPTION 'Plan is not waiting for approval'; END IF; IF client_on_hold(cp.client_id) THEN RAISE EXCEPTION 'This hotel is on hold'; END IF; IF NOT _approve THEN IF coalesce(btrim(_comment),'')='' THEN RAISE EXCEPTION 'Add a comment for requested changes'; END IF; UPDATE activity_plans SET status='changes_requested',comment=btrim(_comment) WHERE id=p.id; RETURN; END IF;
 IF EXISTS(SELECT 1 FROM activity_items i WHERE i.plan_id=p.id AND (SELECT count(DISTINCT a.user_id) FROM client_staff_assignments a JOIN profiles pr ON pr.id=a.user_id AND pr.status='active' WHERE a.client_id=cp.client_id AND a.pipeline_id=cp.pipeline_id AND NOT a.excluded AND a.user_id IN(i.owner_id,i.backup_id))<>2) THEN RAISE EXCEPTION 'The head must update owner and backup assignments before approval'; END IF;
 UPDATE activity_plans SET status='superseded' WHERE family_id=p.family_id AND status='approved'; UPDATE recurring_tasks SET status='superseded' WHERE family_id=p.family_id AND status NOT IN('done','closed','superseded'); UPDATE activity_plans SET status='approved',approved_by=auth.uid(),approved_at=now(),comment=_comment WHERE id=p.id;
 FOR i IN SELECT * FROM activity_items WHERE plan_id=p.id LOOP FOREACH s IN ARRAY ARRAY['preparation','approval','publish'] LOOP IF EXISTS(SELECT 1 FROM recurring_tasks WHERE family_id=p.family_id AND occurrence_key=i.occurrence_key AND stage=s AND status='done') THEN CONTINUE; END IF; d:=CASE s WHEN 'preparation' THEN activity_working_before(i.publish_on,5) WHEN 'approval' THEN activity_working_before(i.publish_on,2) ELSE i.publish_on END; INSERT INTO recurring_tasks(plan_id,item_id,family_id,occurrence_key,stage,due_date,original_due_date,owner_id,backup_id) VALUES(p.id,i.id,p.family_id,i.occurrence_key,s,d,d,i.owner_id,i.backup_id) ON CONFLICT DO NOTHING; END LOOP; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.decide_activity_plan(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_activity_plan(uuid,boolean,text) TO authenticated;
CREATE FUNCTION public.update_recurring_task(_task uuid,_status text,_due date DEFAULT NULL,_reason text DEFAULT NULL,_owner uuid DEFAULT NULL,_backup uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t recurring_tasks;p activity_plans;cp client_pipelines;head boolean; BEGIN PERFORM activity_require_ready(); SELECT * INTO t FROM recurring_tasks WHERE id=_task FOR UPDATE; SELECT * INTO p FROM activity_plans WHERE id=t.plan_id; SELECT * INTO cp FROM client_pipelines WHERE id=p.client_pipeline_id; IF t.id IS NULL OR NOT activity_can_read(cp.id) OR has_role(auth.uid(),'client') THEN RAISE EXCEPTION 'Task not available'; END IF; head:=activity_can_head(cp.id); IF client_on_hold(cp.client_id) THEN RAISE EXCEPTION 'This hotel is on hold'; END IF; IF t.status IN('done','closed','superseded') THEN RAISE EXCEPTION 'Completed and historical tasks are preserved'; END IF; IF NOT(head OR t.owner_id=auth.uid() OR t.backup_id=auth.uid()) THEN RAISE EXCEPTION 'Task owner, backup or head only'; END IF;
 IF _due IS NOT NULL OR _status='closed' OR _owner IS NOT NULL OR _backup IS NOT NULL THEN IF NOT head OR coalesce(btrim(_reason),'')='' THEN RAISE EXCEPTION 'Head review and a reason are required'; END IF; END IF;
 IF _due IS NOT NULL AND _status='closed' THEN RAISE EXCEPTION 'Choose reschedule or close'; END IF;
 IF _due IS NOT NULL AND t.status<>'missed_review' THEN RAISE EXCEPTION 'Only missed tasks can be rescheduled after review'; END IF;
 IF _due IS NULL AND _status NOT IN('not_started','in_progress','done','closed') THEN RAISE EXCEPTION 'Invalid task status'; END IF;
 IF _owner IS NOT NULL OR _backup IS NOT NULL THEN IF coalesce(_owner,t.owner_id)=coalesce(_backup,t.backup_id) OR (SELECT count(DISTINCT a.user_id) FROM client_staff_assignments a WHERE a.client_id=cp.client_id AND a.pipeline_id=cp.pipeline_id AND NOT a.excluded AND a.user_id IN(coalesce(_owner,t.owner_id),coalesce(_backup,t.backup_id)))<>2 THEN RAISE EXCEPTION 'Owner and backup must be different assigned people'; END IF; END IF;
 INSERT INTO activity_task_history(task_id,actor,action,reason,old_due,new_due) VALUES(t.id,auth.uid(),CASE WHEN _due IS NOT NULL THEN 'rescheduled' ELSE _status END,_reason,t.due_date,coalesce(_due,t.due_date)); UPDATE recurring_tasks SET status=CASE WHEN _due IS NOT NULL THEN 'not_started' ELSE _status END,due_date=coalesce(_due,due_date),owner_id=coalesce(_owner,owner_id),backup_id=coalesce(_backup,backup_id),done_at=CASE WHEN _status='done' THEN now() END,done_by=CASE WHEN _status='done' THEN auth.uid() END,review_reason=coalesce(_reason,review_reason) WHERE id=t.id; END $$;
REVOKE ALL ON FUNCTION public.update_recurring_task(uuid,text,date,text,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.update_recurring_task(uuid,text,date,text,uuid,uuid) TO authenticated;
CREATE FUNCTION public.flag_monthly_activity_missed(_today date DEFAULT (now() AT TIME ZONE 'Asia/Kolkata')::date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n int; BEGIN UPDATE recurring_tasks t SET status='missed_review' FROM activity_plans p JOIN client_pipelines cp ON cp.id=p.client_pipeline_id WHERE t.plan_id=p.id AND p.status='approved' AND (p.month+interval '1 month')::date<=_today AND t.status IN('not_started','in_progress') AND t.due_date<_today AND NOT client_on_hold(cp.client_id); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$; REVOKE ALL ON FUNCTION public.flag_monthly_activity_missed(date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.flag_monthly_activity_missed(date) TO service_role;
SELECT cron.schedule('north-star-monthly-activity-review','10 18 * * *','SELECT public.flag_monthly_activity_missed();');